mapper.select:
SELECT pa.id,pa.pork_report_id,pa.slices,pa.weight,pa.place,pa.status,pa.pork_arrange_time FROM meattrade_pork_arrange pa INNER JOIN meattrade_pork_arrange_detail pad ON pa.pork_report_id = pad.pork_report_id
AND pa.pork_arrange_time BETWEEN #{param.period.begin()} AND #{param.period.end()}
AND pa.tenant = 1 AND pad.cheat = 1

select count(DISTINCT pa.id) as cheat_count from meattrade_pork_arrange pa INNER JOIN meattrade_pork_arrange_detail pade ON pa.pork_report_id = pade.pork_report_id
pa.status = 'FINISHED' and pa.tenant = #{param.tenant} and pade.cheat = 1
and pa.pork_report_id in
#{porkReportId}
AND pa.pork_arrange_time BETWEEN #{param.period.begin} AND #{param.period.end}

select
count(pa.id) as arrange_count
from
meattrade_pork_arrange pa

    pa.status = 'FINISHED' and pa.tenant = #{param.tenant}

        and pa.pork_report_id in

            #{porkReportId}



        AND pa.pork_arrange_time BETWEEN #{param.period.begin} AND #{param.period.end}
